116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        // Normalize the address up front so every downstream use (the required-field check,
120	        // household-duplicate detection, the shared household id and the stored/returned value)
121	        // works from the same canonical form.
122	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
123	        List<String> missingFields = new ArrayList<>();
124	        if (isBlank(ownerFieldsDto.getFirstName())) {
125	            missingFields.add("firstName");
126	        }
127	        if (isBlank(ownerFieldsDto.getLastName())) {
128	            missingFields.add("lastName");
129	        }
130	        // Reject an address that is blank once normalized (e.g. whitespace-only input).
131	        if (isBlank(normalizedAddress)) {
132	            missingFields.add("address");
133	        }
134	        if (isBlank(ownerFieldsDto.getCity())) {
135	            missingFields.add("city");
136	        }
137	        if (isBlank(ownerFieldsDto.getTelephone())) {
138	            missingFields.add("telephone");
139	        }
140	        if (!missingFields.isEmpty()) {
141	            throw new InvalidOwnerFieldsException(missingFields);
142	        }
143	        // Determine the effective registration date up front so every downstream use (the daily
144	        // create-limit, the stored value and anything derived from it such as the membership number's
145	        // year segment) works from the same business-day-adjusted date. The effective date is the
146	        // supplied value when present, otherwise the server's current date; a weekend date is rolled
147	        // forward to the following Monday.
148	        LocalDate effectiveRegistrationDate = ownerFieldsDto.getRegistrationDate() != null
149	            ? ownerFieldsDto.getRegistrationDate()
150	            : LocalDate.now();
151	        effectiveRegistrationDate = toBusinessDay(effectiveRegistrationDate);
152	        // Reject the request once the day's owner-creation limit is reached: when 100 or more owners
153	        // already carry this adjusted business day's registration date, no further owners may be
154	        // created for that day.
155	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= MAX_OWNERS_PER_DAY) {
156	            throw new DailyOwnerLimitExceededException(effectiveRegistrationDate);
157	        }
158	        // Reject the request when the owner's city is already full: a city that already holds the
159	        // maximum of 50 owners (compared case-insensitively, as elsewhere) accepts no more.
160	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= MAX_OWNERS_PER_CITY) {
161	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
162	        }
163	        // Normalize the telephone into E.164 form; a number that cannot form a valid
164	        // E.164 value is rejected with a 400.
165	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
166	        // Email is optional; when present it must be a syntactically valid address and is
167	        // stored lower-cased. An invalid address is rejected with a 400.
168	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
169	        // Reject the request if the E.164 telephone is already used by any other owner.
170	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
171	            .map(Owner::getTelephone)
172	            .filter(existing -> existing != null)
173	            .anyMatch(normalizedTelephone::equals);
174	        if (telephoneInUse) {
175	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
176	        }
177	        // Household handling for a matching last name + address (compared case-insensitively with
178	        // collapsed whitespace). By default such a request is rejected as a duplicate household;
179	        // when the caller opts in via 'sharesHousehold' the owner is instead admitted into the shared
180	        // household and every member (the new owner and any existing ones) is stamped with the same
181	        // stable 'householdId'.
182	        String normalizedLastName = collapse(ownerFieldsDto.getLastName());
183	        String householdId = null;
184	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
185	            householdId = householdId(normalizedLastName, normalizedAddress);
186	            // Backfill the shared identifier onto any existing member of this household so the whole
187	            // household carries the same stable value.
188	            for (Owner existing : this.clinicService.findAllOwners()) {
189	                if (collapse(existing.getLastName()).equals(normalizedLastName)
190	                    && normalizeAddress(existing.getAddress()).equals(normalizedAddress)
191	                    && !householdId.equals(existing.getHouseholdId())) {
192	                    existing.setHouseholdId(householdId);
193	                    this.clinicService.saveOwner(existing);
194	                }
195	            }
196	        } else {
197	            boolean householdInUse = this.clinicService.findAllOwners().stream()
198	                .anyMatch(existing -> collapse(existing.getLastName()).equals(normalizedLastName)
199	                    && normalizeAddress(existing.getAddress()).equals(normalizedAddress));
200	            if (householdInUse) {
201	                throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
202	            }
203	        }
204	        HttpHeaders headers = new HttpHeaders();
205	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
206	        owner.setAddress(normalizedAddress);
207	        owner.setTelephone(normalizedTelephone);
208	        owner.setEmail(normalizedEmail);
209	        owner.setHouseholdId(householdId);
210	        // Record how many existing owners (before this create) share this owner's first and last
211	        // name, compared case-insensitively. Computed against the current owners so the new owner
212	        // itself is never counted.
213	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
214	        // Store the business-day-adjusted effective registration date computed above. This defaults
215	        // to the server's current date when none was supplied and rolls any weekend date forward to
216	        // the following Monday, so everything derived from it (e.g. the membership number's year
217	        // segment) uses the adjusted date.
218	        owner.setRegistrationDate(effectiveRegistrationDate);
219	        // Assign the customer code: '<CITY3>-<LAST3>-<NNNN>' where CITY3 is the upper-cased first
220	        // three letters of the city, LAST3 the upper-cased first three letters of the last name and
221	        // NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number of
222	        // owners already in that city.
223	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
224	        this.clinicService.saveOwner(owner);
225	        // Emit an audit trail line for the successful create, carrying the owner id, the assigned
226	        // customer code and the effective registration date.
227	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
228	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
229	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
230	        headers.setLocation(UriComponentsBuilder.newInstance()
231	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
232	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
233	    }
