329	    private static boolean isBlank(String value) {
330	        return value == null || value.trim().isEmpty();
331	    }
332	
333	    /**
334	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
335	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
336	     * compared case-insensitively with collapsed whitespace.
337	     */
338	    private static String collapse(String value) {
339	        if (value == null) {
340	            return "";
341	        }
342	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
343	    }
344	
345	    /**
346	     * Common street-type abbreviations expanded during address normalization.
347	     */
348	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
349	        "ST", "STREET",
350	        "RD", "ROAD",
351	        "AVE", "AVENUE");
352	
353	    /**
354	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
355	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
356	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
357	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
358	     * address maps to itself.
359	     */
360	    private static String normalizeAddress(String value) {
361	        if (value == null) {
362	            return "";
363	        }
364	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
365	        if (collapsed.isEmpty()) {
366	            return "";
367	        }
368	        String[] tokens = collapsed.split(" ");
369	        StringBuilder sb = new StringBuilder(collapsed.length());
370	        for (int i = 0; i < tokens.length; i++) {
371	            if (i > 0) {
372	                sb.append(' ');
373	            }
374	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
375	        }
376	        return sb.toString();
377	    }
378	
379	    /**
380	     * Derive the stable household identifier shared by owners with the same normalized last name
381	     * and address. It is a deterministic function of those two values, so every member of a
382	     * household independently derives the same identifier: the first 12 upper-case hex characters
383	     * of {@code SHA-256(normalizedLastName + '\n' + normalizedAddress)}.
384	     */
385	    private static String householdId(String normalizedLastName, String normalizedAddress) {
386	        try {
387	            byte[] digest = MessageDigest.getInstance("SHA-256")
388	                .digest((normalizedLastName + "\n" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
389	            StringBuilder sb = new StringBuilder(digest.length * 2);
390	            for (byte b : digest) {
391	                sb.append(String.format("%02x", b));
392	            }
393	            return sb.substring(0, 12).toUpperCase();
394	        }
395	        catch (NoSuchAlgorithmException e) {
396	            throw new IllegalStateException("SHA-256 not available", e);
397	        }
398	    }
399	
400	    /**
401	     * Build the customer code for a new owner: {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the
402	     * upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
403	     * last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than the
404	     * number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
405	     */
406	    /**
407	     * Count the existing owners that share the given first and last name, compared
408	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
409	     * namesakes that already existed at creation time (the new owner itself is not included).
410	     */
411	    private int countNamesakes(String firstName, String lastName) {
412	        return (int) this.clinicService.findAllOwners().stream()
413	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
414	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
415	                && existing.getLastName().equalsIgnoreCase(lastName))
416	            .count();
417	    }
418	
419	    /**
420	     * The maximum number of owners a single city may contain. Once a city holds this many owners a
421	     * request to create another owner in it is rejected as a conflict.
422	     */
423	    private static final int MAX_OWNERS_PER_CITY = 50;
424	
425	    /**
426	     * Count the existing owners registered in the given city, compared case-insensitively (as in
427	     * {@link #nextCustomerCode}). Called before the new owner is saved, so the returned value
428	     * reflects the owners that already existed at creation time.
429	     */
430	    private int countOwnersInCity(String city) {
431	        return (int) this.clinicService.findAllOwners().stream()
432	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
433	            .count();
434	    }
435	
436	    /**
437	     * The maximum number of owners that may be created on a single day. Once this many owners
438	     * already carry a given day's registration date, a request to create another owner that day is
439	     * rejected with a 429.
440	     */
441	    private static final int MAX_OWNERS_PER_DAY = 100;
442	
443	    /**
444	     * Count the existing owners whose registration date is the given day. Called before the new
445	     * owner is saved, so the returned value reflects the owners that already existed at creation
446	     * time.
447	     */
448	    private int countOwnersRegisteredOn(LocalDate date) {
449	        return (int) this.clinicService.findAllOwners().stream()
450	            .filter(existing -> date.equals(existing.getRegistrationDate()))
451	            .count();
452	    }
453	
454	    /**
455	     * Roll a date forward onto a business day: a Saturday or Sunday is advanced to the following
456	     * Monday, while a weekday is returned unchanged. Used so the effective registration date (whether
457	     * supplied or defaulted) always falls on a business day.
458	     */
459	    private static LocalDate toBusinessDay(LocalDate date) {
460	        return switch (date.getDayOfWeek()) {
461	            case SATURDAY -> date.plusDays(2);
462	            case SUNDAY -> date.plusDays(1);
463	            default -> date;
464	        };
465	    }
466	
467	    private String nextCustomerCode(String city, String lastName) {
468	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
469	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
470	        long sequence = this.clinicService.findAllOwners().stream()
471	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
472	            .count() + 1L;
473	        return String.format("%s-%s-%04d", city3, last3, sequence);
474	    }
475	
476	    /**
477	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
478	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
479	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
480	     * The result must be a {@code '+'} followed by 8 to 15 digits, otherwise an
481	     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400.
482	     */
483	    private static String toE164(String raw) {
484	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
485	        boolean hasCountryCode = cleaned.startsWith("+");
486	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
487	        if (!digits.matches("\\d+")) {
488	            throw new InvalidOwnerFieldsException(List.of("telephone"));
489	        }
490	        if (!hasCountryCode) {
491	            if (digits.startsWith("0")) {
492	                digits = digits.substring(1);
493	            }
494	            digits = "61" + digits;
495	        }
496	        if (digits.length() < 8 || digits.length() > 15) {
497	            throw new InvalidOwnerFieldsException(List.of("telephone"));
498	        }
499	        return "+" + digits;
500	    }
501	
502	    /**
503	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
504	     * and a domain with at least one dot-separated label, none of which contain whitespace or
505	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
506	     */
507	    private static final Pattern EMAIL_PATTERN =
508	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
509	
510	    /**
511	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
512	     * supplied (the field is optional). When supplied it must be a syntactically valid address,
513	     * otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a
514	     * 400. A valid address is returned lower-cased.
515	     */
516	    private static String normalizeEmail(String email) {
517	        if (email == null || email.isEmpty()) {
518	            return null;
519	        }
520	        String trimmed = email.trim();
521	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
522	            throw new InvalidOwnerFieldsException(List.of("email"));
523	        }
524	        return trimmed.toLowerCase();
525	    }
526	}
